/**
 * Load audit log entries
 * @param {number} page - Page number for pagination
 * @param {number} pageSize - Number of entries per page
 */
async function loadAuditLog(page, pageSize) {
    if (page == null) page = 1;
    if (pageSize == null) pageSize = 20;

    var tbody = document.getElementById('audit-log-body');
    var emptyState = document.getElementById('audit-log-empty');
    if (!tbody) return;

    try {
        var result = await window.AppUtils.apiRequest('/audit/?page=' + page + '&page_size=' + pageSize);
        if (result && result.data && result.data.length > 0) {
            auditLogState.currentPage = result.page;
            auditLogState.totalPages = result.total_pages;
            renderAuditLogTable(result.data);
            renderPagination(result.page, result.total_pages);
            if (emptyState) emptyState.style.display = 'none';
        } else {
            tbody.innerHTML = '';
            renderPagination(1, 1);
            if (emptyState) emptyState.style.display = 'block';
        }
    } catch (error) {
        console.warn('[AuditLog] Endpoint not available, showing empty table.');
        tbody.innerHTML = '';
        renderPagination(1, 1);
        if (emptyState) emptyState.style.display = 'block';
    }
}

/**
 * Render audit log table
 * @param {Array} entries - Audit log entries
 */
function renderAuditLogTable(entries) {
    var tbody = document.getElementById('audit-log-body');
    if (!tbody) return;

    var html = '';
    for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        html += '<tr>';
        html += '<td class="timestamp-cell">' + formatTimestamp(entry.timestamp) + '</td>';
        html += '<td>' + formatActionType(entry.action) + '</td>';
        html += '<td>' + (entry.description || '\u2014') + '</td>';
        html += '<td class="details-cell">' + (entry.details || '\u2014') + '</td>';
        html += '</tr>';
    }
    tbody.innerHTML = html;
}

/**
 * Format action type for display
 * @param {string} action - Action type
 * @returns {string} - Formatted action with badge class
 */
function formatActionType(action) {
    if (!action) return '\u2014';

    var lower = action.toLowerCase();
    var badgeClass = 'view';

    if (lower.indexOf('login') !== -1) {
        badgeClass = 'login';
    } else if (lower.indexOf('logout') !== -1) {
        badgeClass = 'logout';
    } else if (lower.indexOf('update') !== -1 || lower.indexOf('change') !== -1 || lower.indexOf('edit') !== -1) {
        badgeClass = 'update';
    }

    return '<span class="action-badge ' + badgeClass + '">' + action + '</span>';
}

/**
 * Render pagination controls
 * @param {number} currentPage - Current page number
 * @param {number} totalPages - Total number of pages
 */
function renderPagination(currentPage, totalPages) {
    var container = document.getElementById('audit-log-pagination');
    if (!container) return;

    if (totalPages <= 1) {
        container.innerHTML = '';
        return;
    }

    var html = '';

    // Previous button
    if (currentPage > 1) {
        html += '<button data-page="' + (currentPage - 1) + '">&laquo; Prev</button>';
    } else {
        html += '<button class="disabled" disabled>&laquo; Prev</button>';
    }

    // Page numbers
    for (var p = 1; p <= totalPages; p++) {
        if (p === currentPage) {
            html += '<button class="active" disabled>' + p + '</button>';
        } else {
            html += '<button data-page="' + p + '">' + p + '</button>';
        }
    }

    // Next button
    if (currentPage < totalPages) {
        html += '<button data-page="' + (currentPage + 1) + '">Next &raquo;</button>';
    } else {
        html += '<button class="disabled" disabled>Next &raquo;</button>';
    }

    container.innerHTML = html;

    // Attach click handlers
    var buttons = container.querySelectorAll('button[data-page]');
    for (var i = 0; i < buttons.length; i++) {
        buttons[i].addEventListener('click', function() {
            handlePageChange(parseInt(this.getAttribute('data-page'), 10));
        });
    }
}

/**
 * Handle page change
 * @param {number} newPage - Page number to navigate to
 */
function handlePageChange(newPage) {
    if (newPage < 1 || newPage > auditLogState.totalPages) return;
    loadAuditLog(newPage, auditLogState.pageSize);
}

