/**
 * Dashboard JS - Dashboard page functionality
 */

/** Column definitions for the IDMS table — update labels here when real columns are known */
var IDMS_COLUMNS = [
    { key: 'id', label: 'ID' },
    { key: 'asset_id', label: 'Asset ID' },
    { key: 'site', label: 'Site' },
    { key: 'equipment_type', label: 'Equipment Type' },
    { key: 'status', label: 'Status' },
    { key: 'last_service_date', label: 'Last Service Date' }
];

/**
 * Initialize dashboard page
 */
function initDashboardPage() {
    // DEV: Auth check disabled during development
    // window.AppUtils.requireAuth();
    loadIDMSData();
    initDateRangeInputs();
    loadAPIUsageStats();

    var filterBtn = document.getElementById('filter-btn');
    if (filterBtn) {
        filterBtn.addEventListener('click', handleDateFilter);
    }
}

/**
 * Load IDMS data for the data table
 */
async function loadIDMSData() {
    var tbody = document.getElementById('data-table-body');
    var emptyState = document.getElementById('data-table-empty');
    if (!tbody) return;

    try {
        var result = await window.AppUtils.apiRequest('/dashboard/idms-data');
        if (result && result.data && result.data.length > 0) {
            renderDataTable(result.data);
            if (emptyState) emptyState.style.display = 'none';
        } else {
            tbody.innerHTML = '';
            if (emptyState) emptyState.style.display = 'block';
        }
    } catch (error) {
        console.warn('[Dashboard] IDMS endpoint not available, showing empty table.');
        tbody.innerHTML = '';
        if (emptyState) emptyState.style.display = 'block';
    }
}

/**
 * Render data table with IDMS data
 * @param {Array} data - IDMS data array
 */
function renderDataTable(data) {
    var tbody = document.getElementById('data-table-body');
    if (!tbody) return;

    var html = '';
    for (var i = 0; i < data.length; i++) {
        var row = data[i];
        html += '<tr>';
        for (var j = 0; j < IDMS_COLUMNS.length; j++) {
            var col = IDMS_COLUMNS[j];
            var value = row[col.key];
            // Format dates
            if (col.key === 'last_service_date' && value) {
                value = window.AppUtils.formatDate ? window.AppUtils.formatDate(value) : value;
            }
            html += '<td>' + (value != null ? value : '—') + '</td>';
        }
        html += '</tr>';
    }
    tbody.innerHTML = html;
}

/**
 * Load API usage statistics
 * @param {string} startDate - Start date string (YYYY-MM-DD)
 * @param {string} endDate - End date string (YYYY-MM-DD)
 */
async function loadAPIUsageStats(startDate, endDate) {
    var start = startDate || document.getElementById('start-date').value;
    var end = endDate || document.getElementById('end-date').value;

    try {
        var stats = await window.AppUtils.apiRequest('/dashboard/api-usage?start_date=' + start + '&end_date=' + end);
        renderAPIStats(stats);
    } catch (error) {
        console.warn('[Dashboard] API usage endpoint not available, using placeholder data.');
        renderAPIStats({ total_calls: 0, start_date: start, end_date: end });
    }

    try {
        var breakdown = await window.AppUtils.apiRequest('/dashboard/api-usage/breakdown?start_date=' + start + '&end_date=' + end);
        renderAPIBreakdown(breakdown);
    } catch (error) {
        console.warn('[Dashboard] API breakdown endpoint not available, using placeholder data.');
        renderAPIBreakdown({
            breakdown: [
                { page: 'Login', count: 0, percentage: 0 },
                { page: 'Landing', count: 0, percentage: 0 },
                { page: 'Dashboard', count: 0, percentage: 0 },
                { page: 'Settings', count: 0, percentage: 0 },
                { page: 'Audit Log', count: 0, percentage: 0 }
            ],
            total_calls: 0,
            start_date: start,
            end_date: end
        });
    }
}

/**
 * Render API usage statistics
 * @param {object} stats - API usage statistics
 */
function renderAPIStats(stats) {
    var totalEl = document.getElementById('total-api-calls');
    if (totalEl && stats) {
        totalEl.textContent = stats.total_calls != null ? stats.total_calls : '--';
    }
}

/**
 * Render API breakdown by page
 * @param {object} breakdown - API calls breakdown by page
 */
function renderAPIBreakdown(breakdown) {
    var chart = document.getElementById('api-breakdown-chart');
    if (!chart || !breakdown || !breakdown.breakdown) return;

    var html = '';
    for (var i = 0; i < breakdown.breakdown.length; i++) {
        var item = breakdown.breakdown[i];
        var pct = item.percentage != null ? item.percentage : 0;
        html += '<div class="breakdown-row">';
        html += '  <span class="breakdown-label">' + item.page + '</span>';
        html += '  <div class="breakdown-bar-track">';
        html += '    <div class="breakdown-bar-fill" style="width: ' + pct + '%"></div>';
        html += '  </div>';
        html += '  <span class="breakdown-value">' + item.count + '</span>';
        html += '</div>';
    }

    if (breakdown.breakdown.length === 0) {
        html = '<p class="breakdown-empty">No API usage data for this period.</p>';
    }

    chart.innerHTML = html;
}

/**
 * Handle date range filter
 * @param {Event} event - Filter button click event
 */
function handleDateFilter(event) {
    var start = document.getElementById('start-date').value;
    var end = document.getElementById('end-date').value;

    if (!start || !end) return;
    if (start > end) return;

    loadAPIUsageStats(start, end);
}

/**
 * Initialize date range inputs with default values
 */
function initDateRangeInputs() {
    var endInput = document.getElementById('end-date');
    var startInput = document.getElementById('start-date');
    if (!endInput || !startInput) return;

    var today = new Date();
    var thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(today.getDate() - 30);

    endInput.value = today.toISOString().split('T')[0];
    startInput.value = thirtyDaysAgo.toISOString().split('T')[0];
}

// Initialize on DOM load
document.addEventListener('DOMContentLoaded', function() {
    initDashboardPage();
});

